def make_matrix(size: int) -> list:
    return [[i * size + j for j in range(size)] for i in range(size)]

def matrix_multiply(A: list, B: list) -> list:
    size = len(A)
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                C[i][j] += A[i][k] * B[k][j]
    return C

